INSERT INTO ntss.sys_data_set
(sql_cd, "sql", db_class, detail, can_repeat, use_application, report_class, memo, reg_date, up_date, pre_sql_info)
VALUES(12, 'WITH rst_start_data_check AS (
    SELECT CASE WHEN rst_start_date IS NULL THEN up_date ELSE rst_start_date END AS rst_start_date
    FROM ord_main
    WHERE ord_no = @ordNo
    AND is_del = ''0''
    AND rst_dialysis_state > ''0''
),
	b AS (
    select ord_main.* from ord_main
     where rst_dialysis_state between ''1'' and ''5''
     and
		ord_no = @ordNo
     and
       is_del = ''0''
), d AS (
    select b.ord_no
    , data_type
    , MAX(bio_moni_ctl_no) AS bio_moni_ctl_no
    from b inner join mni_monitor on (b.ord_no = mni_monitor.ord_no)
    group by b.ord_no
    , mni_monitor.data_type
), e AS (
    select mni_monitor.*,
    to_number(mni_monitor.monitor_data::json->>''1'', ''9999'') AS 経過時間
    , to_number(mni_monitor.monitor_data::json->>''3'', ''9999'') AS 残り時間_除水完了
    , to_number(mni_monitor.monitor_data::json->>''4'', ''9999'') AS 残り時間_透析完了
    from d
    inner join mni_monitor on (d.bio_moni_ctl_no = mni_monitor.bio_moni_ctl_no)
    where d.data_type = 1
), f AS (
    select e.*
    , e.経過時間 + e.残り時間_除水完了 AS 予測時間_除水
    , e.経過時間 + e.残り時間_透析完了 AS 予測時間_透析
    from e
),g as (
select
-- 終了予定
b.rst_start_date + e.経過時間  * interval ''1 minute'' AS  ind_end_date,
-- 終了予測
CASE WHEN b.rst_dialysis_state < ''3'' THEN null
       WHEN f.残り時間_除水完了 > f.残り時間_透析完了 THEN b.rst_start_date + f.予測時間_除水 * interval ''1 minute''
       ELSE b.rst_start_date + f.予測時間_透析 * interval ''1 minute''
  END AS ind_end_date_time
-- 透析開始
, b.rst_start_date
-- 透析終了
, b.rst_end_date
, b.ord_no
from  b left join e on b.ord_no = e.ord_no left join f on b.ord_no = f.ord_no)
select g.rst_start_date,g.rst_end_date,g.ind_end_date_time,g.ind_end_date,
ord.ord_no,
ord.treat_date,
    s.rst_weight_info ->> ''ctr'' as last_ctr
  , s.rst_weight_info ->> ''ctr_weight'' as last_ctr_weight
  , s.rst_weight_info ->> ''weight_before'' as last_weight_before
  , s.rst_weight_info ->> ''weight_after'' as last_weight_after
  , s.rst_weight_info ->> ''weight_decreased'' as last_weight_decreased
  , substr(to_char(cast( s.rst_weight_info ->> ''ctr_measure_date''  as TIMESTAMP),''YYYY/MM/DD hh24:mi:ss''),0,17)  as last_ctr_measure_date
  , substr(to_char(cast( s.rst_weight_info ->> ''weight_after_date''  as TIMESTAMP),''YYYY/MM/DD hh24:mi:ss''),0,17)  as last_weight_after_date
  , substr(to_char(cast( s.rst_weight_info ->> ''weight_before_date''  as TIMESTAMP),''YYYY/MM/DD hh24:mi:ss''),0,17)  as last_weight_before_date
  , (s.rst_puncture_user_info ->> ''user_last_name_1'') || (s.rst_puncture_user_info ->> ''user_first_name_1'') as last_puncture_user_name
from
  ord_main as ord   LEFT OUTER JOIN ord_main s ON (
    ord.ord_no <> s.ord_no
    AND ord.pat_id = s.pat_id
    AND ord.facility_cd = s.facility_cd
    AND (SELECT rst_start_date FROM rst_start_data_check) > s.rst_start_date
    AND s.is_del = ''0''
  )
	left join g
	on ord.ord_no=g.ord_no
WHERE
  ord.ord_no = @ordNo
AND
  ord.is_del = ''0''
AND ord.rst_dialysis_state > ''0''
ORDER BY
  s.rst_start_date DESC
LIMIT
 1', 2, '[{"preview": "56.78", "can_calc": "1", "data_code": "last_weight_before", "data_name": "前体重(前回)", "data_type": "decimal", "conv_table": [], "data_class": "体重情報(過去実績)", "field_name": "last_weight_before", "disp_format": "0.00", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "2011/3/12  8:21", "can_calc": "1", "data_code": "last_weight_before_date", "data_name": "前体重測定日時(前回)", "data_type": "DateTime", "conv_table": [], "data_class": "体重情報(過去実績)", "field_name": "last_weight_before_date", "disp_format": "yyyy/mm/dd", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "56.78", "can_calc": "1", "data_code": "last_weight_after", "data_name": "後体重(前回)", "data_type": "decimal", "conv_table": [], "data_class": "体重情報(過去実績)", "field_name": "last_weight_after", "disp_format": "0.00", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "2011/3/12  8:21", "can_calc": "1", "data_code": "last_weight_after_date", "data_name": "後体重測定日時(前回)", "data_type": "DateTime", "conv_table": [], "data_class": "体重情報(過去実績)", "field_name": "last_weight_after_date", "disp_format": "yyyy/mm/dd", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "50", "can_calc": "1", "data_code": "last_ctr", "data_name": "CTR(前回)", "data_type": "decimal", "conv_table": [], "data_class": "体重情報(過去実績)", "field_name": "last_ctr", "disp_format": "0.00", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "2011/3/12  8:21", "can_calc": "1", "data_code": "last_ctr_measure_date", "data_name": "CTR測定日時(前回)", "data_type": "DateTime", "conv_table": [], "data_class": "体重情報(過去実績)", "field_name": "last_ctr_measure_date", "disp_format": "yyyy/mm/dd", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "56.78", "can_calc": "1", "data_code": "last_ctr_weight", "data_name": "CTR測定時体重(前回)", "data_type": "decimal", "conv_table": [], "data_class": "体重情報(過去実績)", "field_name": "last_ctr_weight", "disp_format": "0.00", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}]'::jsonb, '0', '{"applications": [1]}'::jsonb, '{"classes": [1, 2, 3, 9, 10, 11]}'::jsonb, '実績(前回体重)', '2021-10-06 09:47:33.000', CURRENT_TIMESTAMP, NULL);
INSERT INTO ntss.sys_data_set
(sql_cd, "sql", db_class, detail, can_repeat, use_application, report_class, memo, reg_date, up_date, pre_sql_info)
VALUES(22, '{"collection": "pat_main_history", "eq": {"pat_id": "@patId", "facility_cd": "@facilityCd", "is_del": "0"}, "lt": {"up_date": "@toDate"}, "sort": {"up_date": "desc"}, "slice": {"up_date": 1}_taboo_allergy_info}', 4, '[{"preview": "禁忌", "can_calc": "0", "data_code": "taboo_allergy_class", "data_name": "禁忌アレルギー区分", "data_type": "string", "conv_table": [{"code": "1", "disp": "禁忌", "item": "禁忌"}, {"code": "2", "disp": "アレルギー", "item": "アレルギー"}], "data_class": "禁忌・アレルギー", "field_name": "taboo_allergy_class", "disp_format": "", "data_category": "患者情報", "facility_table": "", "facility_filter_type": "0"}, {"preview": "テスト薬剤(禁忌・アレルギー)", "can_calc": "0", "data_code": "content", "data_name": "内容", "data_type": "string", "conv_table": [], "data_class": "禁忌・アレルギー", "field_name": "content", "disp_format": "", "data_category": "患者情報", "facility_table": "", "facility_filter_type": "0"}, {"preview": "禁忌・アレルギーです。", "can_calc": "0", "data_code": "memo", "data_name": "備考", "data_type": "string", "conv_table": [], "data_class": "禁忌・アレルギー", "field_name": "memo", "disp_format": "", "data_category": "患者情報", "facility_table": "", "facility_filter_type": "0"}]'::jsonb, '1', '{"applications": [1]}'::jsonb, '{"classes": [1, 2, 3, 9, 10, 11]}'::jsonb, '患者情報：禁忌・アレルギー　@patId使用', '2021-10-12 11:10:07.240', CURRENT_TIMESTAMP, NULL);
INSERT INTO ntss.sys_data_set
(sql_cd, "sql", db_class, detail, can_repeat, use_application, report_class, memo, reg_date, up_date, pre_sql_info)
VALUES(29, 'WITH infection_order AS (
  select
    one_json ->> ''code'' as infection_cd
    , json_idx as infection_cd_order
from
    mst_selector
    cross join lateral jsonb_array_elements(order_settings -> ''items'') with ordinality as tmp(one_json, json_idx)
where
    facility_cd = @facilityCd
    and master_physical_name = ''mst_exam_item''
),
result_table as (
select
  info->>''item_cd'' as item_cd,
  item.in_hospital_cd1 as in_hospital_cd1,
  item.in_hospital_cd2 as in_hospital_cd2,
  item.in_hospital_cd3 as in_hospital_cd3,
  item.sbt_cd1 as sbt_cd1,
  item.sbt_cd2 as sbt_cd2,
  item.sbt_cd3 as sbt_cd3,
  info->>''item_name'' as item_name,
  info->>''result'' as result,
  info->>''unit'' as unit,
  info->>''freememo'' as freememo,
  p.result_exam_date as result_exam_date,
  p.reg_exam_date,
  p.reg_order_class,
  case p.reg_order_class
  when ''0'' then ''9''
  else p.reg_order_class
  end as reg_order_class_sort,
  p.exam_main_cd as exam_main_cd,
  case
		when info->>''upper''::TEXT = ''null'' then ''''
		when info->>''upper''::TEXT is null then ''''
		else info->>''upper''::TEXT end as upper,
  case
		when info->>''lower''::TEXT = ''null'' then ''''
		when info->>''lower''::TEXT is null then ''''
		else info->>''lower''::TEXT end as lower
from (
  select
    m.*
  from
    pat_exam_main as m
  where
    m.is_del = ''0''
    and m.exam_status = ''1''
    and m.pat_id = @patId
	AND m.facility_cd = @facilityCd
    and m.result_exam_date between date_trunc(''day'', @fromDate ::timestamp) and date_trunc(''day'', @toDate ::timestamp) + ''1 days - 1 milliseconds''
    order by m.result_exam_date desc
  ) as p
  cross join lateral
  json_array_elements (p.exam_result_info :: json) info
  left outer join
  mst_exam_item as item on info->>''item_cd'' = (item.exam_item_cd || '''') and item.is_del =''0'' and is_disp =''1''
	  left join   infection_order as inf   on info->>''item_cd''::text=inf.infection_cd
ORDER BY
  result_exam_date, ARRAY_POSITION(ARRAY[''1'',''2'',''0''], reg_order_class),infection_cd_order
)

SELECT rt.*, case when lower = '''' and upper = '''' then '''' else COALESCE(lower, '''') || ''~'' || COALESCE(upper, '''')  end as normal_value FROM result_table AS rt
