INSERT INTO ntss.sys_data_set
(sql_cd, "sql", db_class, detail, can_repeat, use_application, report_class, memo, reg_date, up_date, pre_sql_info)
VALUES(99, 'with current_ord AS (
    select pat_id, treat_date, rst_start_date, ord_no
    from ord_main
    where ord_no = @ordNo
    and is_del = ''0''
    and rst_dialysis_state <>''0''
),
hist_ord_nos as (
  select
    ord_main.ord_no
    ,ord_main.rst_start_date
  from
    ord_main INNER JOIN current_ord ON ord_main.pat_id = current_ord.pat_id
  where    rst_dialysis_state > ''4''
    and ord_main.ord_no <> @ordNo
    and (((current_ord.rst_start_date is not null) and (ord_main.rst_start_date <= current_ord.rst_start_date))
        or
         ((current_ord.rst_start_date is null) and (ord_main.rst_start_date is not null) and (ord_main.treat_date <= current_ord.treat_date)))
    and is_del = ''0''
  order by rst_start_date desc limit 2
)
, ord_hist_tbl as (
  select rst_start_date
    ,to_number(rst_weight_info->>''weight_before'', ''999.99'') as weight_before
    ,(rst_weight_info->>''weight_before_date'')::timestamp as weight_before_date
    ,to_number(rst_weight_info->>''weight_after'', ''999.99'') as weight_after
    ,(rst_weight_info->>''weight_after_date'')::timestamp as weight_after_date
    ,to_number(rst_weight_info->>''water_removal_rst'', ''999.99'') as water_removal_rst
  from
    ord_main
  where
    ord_no in (select ord_no from hist_ord_nos)
  and is_del = ''0''
  and rst_dialysis_state <>''0''
), ord_array_tbl as (
  select
    array_agg(weight_before order by rst_start_date desc) as array_weight_before
    ,array_agg(weight_before_date order by rst_start_date desc) as array_weight_before_date
    ,array_agg(weight_after order by rst_start_date desc) as array_weight_after
    ,array_agg(weight_after_date order by rst_start_date desc) as array_weight_after_date
    ,array_agg(water_removal_rst order by rst_start_date desc) as array_water_removal_rst
    ,@ordNo as ord_no_t
  from
    ord_hist_tbl
)
select ord_no,array_water_removal_rst[1] as water_removal_rst_prev
  ,array_weight_before[2] as weight_before_prev_prev
  ,array_weight_before_date[2] as weight_before_date_prev_prev
  ,array_weight_after[2] as weight_after_prev_prev
  ,array_weight_after_date[2] as weight_after_date_prev_prev
  ,array_water_removal_rst[2] as water_removal_rst_prev_prev
  ,treat_date
from
  ord_array_tbl
left join current_ord on ord_array_tbl.ord_no_t = current_ord.ord_no
;', 2, '[{"preview": "2.00", "can_calc": "1", "data_code": "water_removal_rst_prev", "data_name": "実績除水量(前回)", "data_type": "decimal", "conv_table": [], "data_class": "体重情報(過去実績)", "field_name": "water_removal_rst_prev", "disp_format": "0.00", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "58.20", "can_calc": "1", "data_code": "weight_before_prev_prev", "data_name": "前体重(前々回)", "data_type": "decimal", "conv_table": [], "data_class": "体重情報(過去実績)", "field_name": "weight_before_prev_prev", "disp_format": "0.00", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "2011/03/08", "can_calc": "0", "data_code": "weight_before_date_prev_prev", "data_name": "前体重測定日時(前々回)", "data_type": "DateTime", "conv_table": [], "data_class": "体重情報(過去実績)", "field_name": "weight_before_date_prev_prev", "disp_format": "yyyy/mm/dd", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "55.30", "can_calc": "1", "data_code": "weight_after_prev_prev", "data_name": "後体重(前々回)", "data_type": "decimal", "conv_table": [], "data_class": "体重情報(過去実績)", "field_name": "weight_after_prev_prev", "disp_format": "0.00", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "2011/03/08", "can_calc": "0", "data_code": "weight_after_date_prev_prev", "data_name": "後体重測定日時(前々回)", "data_type": "DateTime", "conv_table": [], "data_class": "体重情報(過去実績)", "field_name": "weight_after_date_prev_prev", "disp_format": "yyyy/mm/dd", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "2.10", "can_calc": "1", "data_code": "water_removal_rst_prev_prev", "data_name": "実績除水量(前々回)", "data_type": "decimal", "conv_table": [], "data_class": "体重情報(過去実績)", "field_name": "water_removal_rst_prev_prev", "disp_format": "0.00", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}]'::jsonb, '0', '{"applications": [1]}'::jsonb, '{"classes": [1, 2, 3, 9, 10, 11]}'::jsonb, '実績：体重情報(過去実績) @ordNo 使用', '2020-03-31 23:59:59.000', CURRENT_TIMESTAMP, NULL);
INSERT INTO ntss.sys_data_set
(sql_cd, "sql", db_class, detail, can_repeat, use_application, report_class, memo, reg_date, up_date, pre_sql_info)
VALUES(100, 'WITH otc as (
  select
    * 
  from
    ord_treat_condition 
  where
    ord_no = @ordNo
    and facility_cd = @facilityCd
    and is_del = ''0'' 
    and is_disp = ''1''
  order by
    receive_date
)
select
  receive_date
  ,treat_class
  ,treat_condition ->> ''0'' as tc_0 -- 患者コード
  ,treat_condition ->> ''14'' as tc_14 -- 透析時間
  ,treat_condition ->> ''15'' as tc_15 -- 治療モード
  ,treat_condition ->> ''16'' as tc_16 -- ＥＣＵＭ選択
