": "〇", "can_calc": "0", "data_code": "medical_materials__before", "data_name": "医療材料(修正前)", "data_type": "string", "conv_table": [], "data_class": "修正内容", "field_name": "medical_materials__before", "disp_format": "", "data_category": "指示", "facility_table": "", "facility_filter_type": "0"}, {"preview": "〇", "can_calc": "0", "data_code": "medical_materials__after", "data_name": "医療材料(修正後)", "data_type": "string", "conv_table": [], "data_class": "修正内容", "field_name": "medical_materials__after", "disp_format": "", "data_category": "指示", "facility_table": "", "facility_filter_type": "0"}, {"preview": "〇", "can_calc": "0", "data_code": "instructional_comment__before", "data_name": "指示コメント(修正前)", "data_type": "string", "conv_table": [], "data_class": "修正内容", "field_name": "instructional_comment__before", "disp_format": "", "data_category": "指示", "facility_table": "", "facility_filter_type": "0"}, {"preview": "〇", "can_calc": "0", "data_code": "instructional_comment__after", "data_name": "指示コメント(修正後)", "data_type": "string", "conv_table": [], "data_class": "修正内容", "field_name": "instructional_comment__after", "disp_format": "", "data_category": "指示", "facility_table": "", "facility_filter_type": "0"}]'::jsonb, '1', '{"applications": [1]}'::jsonb, '{"classes": [1, 2, 3, 9, 10, 11]}'::jsonb, '修正内容：指示', '2020-07-31 18:29:49.000', CURRENT_TIMESTAMP, NULL);
INSERT INTO ntss.sys_data_set
(sql_cd, "sql", db_class, detail, can_repeat, use_application, report_class, memo, reg_date, up_date, pre_sql_info)
VALUES(197, 'with result_table as (
SELECT
	info ->> ''item_cd'' AS item_cd,
	info ->> ''item_name'' AS item_name,
	info ->> ''result'' AS RESULT,
	info ->> ''unit'' AS unit,
	info ->> ''freememo'' AS freememo,
	info ->> ''upper'' AS UPPER,
	info ->> ''lower'' AS LOWER,
	P.result_exam_date AS result_exam_date,
	P.reg_exam_date,
	P.reg_order_class,
	p.exam_main_cd as exam_main_cd,
	P.pat_id AS pat_id,
	CASE
			WHEN info ->> ''lower'' IS NULL OR info ->> ''lower'' = ''null'' THEN ''''
			WHEN info ->> ''upper'' IS NULL OR info ->> ''upper'' = ''null'' THEN ''''
			ELSE CAST(info ->> ''lower'' AS VARCHAR) || ''~'' || CAST(info ->> ''upper'' AS VARCHAR)
	END AS normal_value
FROM
	(
	SELECT M
		.*
	FROM
		pat_exam_main AS M
	WHERE
		M.is_del = ''0''
		AND M.exam_status = ''1''
		AND M.pat_id in (@patIds)
		AND M.facility_Cd = @facilityCd
		AND M.result_exam_date BETWEEN date_trunc( ''day'', @fromDate :: TIMESTAMP )
		AND date_trunc( ''day'', @toDate :: TIMESTAMP ) + ''1 days - 1 milliseconds''
		AND M.reg_order_class in (@regOrderClassList)
	ORDER BY
		M.result_exam_date DESC
	)
	AS P cross join lateral jsonb_array_elements(P.exam_result_info) with ordinality as tmp(info, json_idx)
ORDER BY
	pat_id,json_idx
),
exam_sort AS(
	SELECT
		index_no AS code_order,
		TO_NUMBER(info ->> ''code'', ''999999999999'') AS code,
		info ->> ''name'' AS name
	FROM
		mst_selector
		CROSS JOIN LATERAL jsonb_array_elements (order_settings -> ''items'') WITH ORDINALITY AS tmp (info, index_no)
	WHERE
		facility_cd = @facilityCd
		AND master_physical_name = ''mst_exam_item''
),
examSet_table as (
	SELECT DISTINCT
		info ->> ''exam_item_cd'' AS exam_item_cd
	FROM
	  mst_exam_set as mes cross join lateral jsonb_array_elements(mes.exam_item_info) with ordinality as tmp(info, json_idx)
	WHERE
		exam_set_cd = @selectExamSetCd
		AND is_disp = ''1''
		AND is_del = ''0''
		AND facility_Cd = @facilityCd
)
, normal_value_set as (
	SELECT value FROM mst_facility_setting WHERE facility_cd = @facilityCd AND facility_setting_no = ''1017''
)
, exam_item_tbl as (
	SELECT
		mei.exam_item_cd,
		exam_item_name,
		unit AS exam_unit,
		CASE
			WHEN normal_value_class = ''1'' AND (SELECT value FROM normal_value_set) = ''1'' THEN normal_value_upper_m
			WHEN normal_value_class = ''1'' AND (SELECT value FROM normal_value_set) = ''2'' THEN normal_value_upper_w
			ELSE normal_value_upper
		END AS exam_upper,
		CASE
			WHEN normal_value_class = ''1'' AND (SELECT value FROM normal_value_set) = ''1'' THEN normal_value_lower_m
			WHEN normal_value_class = ''1'' AND (SELECT value FROM normal_value_set) = ''2'' THEN normal_value_lower_w
			ELSE normal_value_lower
		END AS exam_lower,
		CASE
			WHEN normal_value_class = ''1'' AND (SELECT value FROM normal_value_set) = ''1'' THEN 
				(CASE
					WHEN normal_value_lower_m IS NULL OR normal_value_lower_m = ''null'' THEN ''''
					WHEN normal_value_upper_m IS NULL OR normal_value_upper_m = ''null'' THEN ''''
					ELSE normal_value_lower_m || ''~'' || normal_value_upper_m
				END)
			WHEN normal_value_class = ''1'' AND (SELECT value FROM normal_value_set) = ''2'' THEN 
				(CASE
					WHEN normal_value_lower_w IS NULL OR normal_value_lower_w = ''null'' THEN ''''
					WHEN normal_value_upper_w IS NULL OR normal_value_upper_w = ''null'' THEN ''''
					ELSE normal_value_lower_w || ''~'' || normal_value_upper_w
				END)
			ELSE 
				(CASE
					WHEN normal_value_lower IS NULL OR normal_value_lower = ''null'' THEN ''''
					WHEN normal_value_upper IS NULL OR normal_value_upper = ''null'' THEN ''''
					ELSE normal_value_lower || ''~'' || normal_value_upper
				END)
		END AS exam_normal_value,
		in_hospital_cd1,
		in_hospital_cd2,
		in_hospital_cd3,
		sbt_cd1,
		sbt_cd2,
		sbt_cd3,
		exam_sort.code_order
	FROM
	  mst_exam_item as mei
	LEFT JOIN examSet_table AS et ON CAST(et.exam_item_cd AS NUMERIC) = mei.exam_item_cd
	LEFT JOIN exam_sort ON exam_sort.code = mei.exam_item_cd
	WHERE
		is_disp = ''1''
		AND is_del = ''0''
		AND facility_Cd = @facilityCd
		AND @selectExamSetCd = -1 OR et.exam_item_cd IS NOT NULL
)

SELECT
	rt.pat_id,
	rt.exam_main_cd,
	rt.result_exam_date,
	rt.reg_exam_date,
	rt.reg_order_class,
	CASE 
		WHEN rt.item_cd IS NOT NULL AND rt.item_cd != '''' THEN CAST(rt.item_cd AS NUMERIC)
		ELSE eit.exam_item_cd
	END AS item_cd,
	CASE 
		WHEN rt.item_name IS NOT NULL AND rt.item_name != '''' THEN rt.item_name
		ELSE eit.exam_item_name
	END AS item_name,
	CASE 
		WHEN rt.unit IS NOT NULL AND rt.unit != '''' THEN rt.unit
		ELSE eit.exam_unit
	END AS unit,
	CASE 
		WHEN rt.UPPER IS NOT NULL AND rt.UPPER != '''' THEN rt.UPPER
		ELSE eit.exam_upper
	END AS UPPER,
	CASE 
		WHEN rt.LOWER IS NOT NULL AND rt.LOWER != '''' THEN rt.LOWER
		ELSE eit.exam_lower
	END AS LOWER,
	CASE 
		WHEN rt.normal_value IS NOT NULL AND rt.normal_value != '''' THEN rt.normal_value
		ELSE eit.exam_normal_value
	END AS normal_value,
	rt.RESULT,
	rt.freememo
FROM
	exam_item_tbl AS eit
LEFT JOIN result_table AS rt ON eit.exam_item_cd = CAST(rt.item_cd AS NUMERIC)
ORDER BY eit.code_order, rt.result_exam_date, ARRAY_POSITION(ARRAY[''1'',''2'',''0''], rt.reg_order_class);
