(sql_cd, "sql", db_class, detail, can_repeat, use_application, report_class, memo, reg_date, up_date, pre_sql_info)
VALUES(200, 'WITH DATA AS (

	with ord_tbl AS (
--     SELECT
--         ord_no
--         , facility_cd
--     FROM
--         ord_main
        SELECT
        ord_no
                , medi
                , json_idx
        , facility_cd
    FROM
        ord_main
                CROSS JOIN LATERAL jsonb_array_elements (rst_medi_info) WITH ORDINALITY AS tmp (medi, json_idx)
    WHERE
        is_del = ''0''
        AND ord_no = @ordNo
)
, medicine_order AS (
    select
        one_json ->> ''code'' as medicine_cd
        , json_idx as medicine_cd_order
    from
        mst_selector
        cross join lateral jsonb_array_elements(order_settings -> ''items'') with ordinality as tmp(one_json, json_idx)
    where
        facility_cd = (select facility_cd from ord_tbl limit 1)
        and master_physical_name = ''mst_medicine''
),
medicine_mix_temp AS (

select
    mix.facility_cd
    , mix.medicine_mix_cd
    , medimix ->> ''cd'' as medi_cd
    , medimix ->> ''amount'' as amount
from
    mst_medicine_mix mix
    CROSS JOIN LATERAL jsonb_array_elements(mix_info) WITH ORDINALITY AS tmp(medimix, json_idx)
where mix.is_del = ''0''
    and mix.is_disp = ''1''
)
SELECT A.* from (select
    @ordNo as ord_no_t
    , supplies_base_date as treat_date
		,sv.supplies_cd
    , med.medicine_name as medicine_name
    , md.medicine_cd_order
		, CASE WHEN ( medi ->> ''class_cd'' ) :: TEXT = ''-1'' or (medi ->> ''class_cd'') IS NULL THEN ''未分類'' ELSE medi ->> ''class_name'' END as medi_class_name
-- 		,medi ->> ''class_name'' as medi_class_name
    , sum(sv.ind_rst_value :: NUMERIC) as amount
    , med.unit
    ,sum(sv.receipt_value :: NUMERIC) as receipt_value
    ,med.unit_second as unit_second
--     , med.in_hospital_cd_1 as med_in_hospital_cd_1
--     , med.in_hospital_cd_2 as med_in_hospital_cd_2
--     , med.in_hospital_cd_3 as med_in_hospital_cd_3
--
-- from
--     ord_material_save sv
        , med_clss.class_cd as medi_class_cd
        , case when ord_tbl.medi ->> ''medicine_type'' is null then ''0'' else ord_tbl.medi ->> ''medicine_type'' end as medicine_type
    , med.in_hospital_cd_1 as med_in_hospital_cd_1
    , med.in_hospital_cd_2 as med_in_hospital_cd_2
    , med.in_hospital_cd_3 as med_in_hospital_cd_3

from
   ord_tbl
	 inner join mst_medicine as  med  on (ord_tbl.medi ->> ''cd'' = med.medicine_cd :: text and med.is_del = ''0'' and med.is_disp = ''1'' and med.facility_cd = ord_tbl.facility_cd )
    left join mst_medicine_class as med_clss
        on (med_clss.class_cd = med.class_cd)
		left join ord_material_save as sv on (sv.supplies_base_no = ord_tbl.ord_no and ord_tbl.facility_cd = sv.facility_cd and  medi ->> ''cd'' :: text  = sv.supplies_cd and sv.supplies_source_class in (''1'', ''3'') and sv.ind_rst_class =''2'' and sv.supplies_class not in (''13'',''15'') )
		left join medicine_order md
        on (
            sv.supplies_base_no = sv.supplies_base_no
            and sv.supplies_cd = md.medicine_cd
        )
		
where
    ord_tbl.medi->>''medicine_type'' = ''1''
group by
    sv.supplies_cd
    , medicine_name
    , medicine_cd_order
    , class_name
		,medi_class_name
    , unit
    ,unit_second
        , medi_class_cd--
        , medicine_type--
    , med_in_hospital_cd_1
    , med_in_hospital_cd_2
    , med_in_hospital_cd_3
    , treat_date
	UNION
	select
    @ordNo as ord_no_t
    , supplies_base_date as treat_date
		,sv.supplies_cd
    , med.medicine_name as medicine_name
    , md.medicine_cd_order
		, CASE WHEN ( medi ->> ''class_cd'' ) :: TEXT = ''-1'' or (medi ->> ''class_cd'') IS NULL THEN ''未分類'' ELSE medi ->> ''class_name'' END as medi_class_name
    , sum(sv.ind_rst_value :: NUMERIC) as amount
    , med.unit
    ,sum(sv.receipt_value :: NUMERIC) as receipt_value
    ,med.unit_second as unit_second
        , med_clss.class_cd as medi_class_cd
        , case when ord_tbl.medi ->> ''medicine_type'' is null then ''0'' else ord_tbl.medi ->> ''medicine_type'' end as medicine_type
    , med.in_hospital_cd_1 as med_in_hospital_cd_1
    , med.in_hospital_cd_2 as med_in_hospital_cd_2
    , med.in_hospital_cd_3 as med_in_hospital_cd_3

from
    ord_tbl
		inner join  medicine_mix_temp  mixtemp on (mixtemp.medicine_mix_cd :: text= medi ->> ''cd'' )
	 left join mst_medicine as  med  on (med.medicine_cd :: text = mixtemp.medi_cd and med.is_del = ''0'' and med.is_disp = ''1'' and med.facility_cd = ord_tbl.facility_cd )
    left join mst_medicine_class as med_clss
        on (med_clss.class_cd = med.class_cd)
		left join ord_material_save as sv on (sv.supplies_base_no = ord_tbl.ord_no and ord_tbl.facility_cd = sv.facility_cd and mixtemp.medi_cd  :: text :: text  = sv.supplies_cd and sv.supplies_source_class in (''1'', ''3'') and sv.ind_rst_class =''2'' and sv.supplies_class not in (''13'',''15'') )
		left join medicine_order md
        on (
            sv.supplies_base_no = sv.supplies_base_no
            and sv.supplies_cd = md.medicine_cd
        )
		
where
    ord_tbl.medi->>''medicine_type'' = ''2''
group by
    sv.supplies_cd
    , medicine_name
    , medicine_cd_order
    , class_name
		,medi_class_name
    , unit
    ,unit_second
        , medi_class_cd--
        , medicine_type--
    , med_in_hospital_cd_1
    , med_in_hospital_cd_2
    , med_in_hospital_cd_3
    , treat_date	) A
order by
    A.medicine_cd_order asc

	),
time_info AS (
	WITH b AS (
    select ord_main.* from ord_main
     where rst_dialysis_state between ''1'' and ''5''
     and
			ord_no = @ordNo
     and
       is_del = ''0''
	), d AS (
    select b.ord_no
    , data_type
    , MAX(bio_moni_ctl_no) AS bio_moni_ctl_no
    from b inner join mni_monitor on (b.ord_no = mni_monitor.ord_no)
    group by b.ord_no
    , mni_monitor.data_type
	), e AS (
    select mni_monitor.*,
    to_number(mni_monitor.monitor_data::json->>''1'', ''9999'') AS 経過時間
    , to_number(mni_monitor.monitor_data::json->>''3'', ''9999'') AS 残り時間_除水完了
    , to_number(mni_monitor.monitor_data::json->>''4'', ''9999'') AS 残り時間_透析完了
    from d
    inner join mni_monitor on (d.bio_moni_ctl_no = mni_monitor.bio_moni_ctl_no)
    where d.data_type = 1
	), f AS (
    select e.*
    , e.経過時間 + e.残り時間_除水完了 AS 予測時間_除水
    , e.経過時間 + e.残り時間_透析完了 AS 予測時間_透析
    from e
	)
	select
	b.ord_no as ordnob,
	-- 終了予定
	b.rst_start_date + e.経過時間  * interval ''1 minute'' AS  ind_end_date,
	-- 終了予測
	CASE WHEN b.rst_dialysis_state < ''3'' THEN null
       WHEN f.残り時間_除水完了 > f.残り時間_透析完了 THEN b.rst_start_date + f.予測時間_除水 * interval ''1 minute''
       ELSE b.rst_start_date + f.予測時間_透析 * interval ''1 minute''
	END AS ind_end_date_time
	-- 透析開始
	, b.rst_start_date
	-- 透析終了
	, b.rst_end_date
	from  b left JOIN e on b.ord_no=e.ord_no left JOIN f on b.ord_no=f.ord_no
)
SELECT
DATA.ord_no_t as ord_no,
	*
FROM
	DATA
	LEFT JOIN
	time_info
	on
	DATA.ord_no_t = time_info.ordnob
	;
	', 2, '[{"preview": "実施薬剤１", "can_calc": "0", "data_code": "medicine_name", "data_name": "薬剤名", "data_type": "string", "conv_table": [], "data_class": "実施薬剤(分解)", "field_name": "medicine_name", "disp_format": "", "filter_type": "Medicine", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "透析液", "can_calc": "0", "data_code": "medi_class_name", "data_name": "薬剤分類名", "data_type": "string", "conv_table": [], "data_class": "実施薬剤(分解)", "field_name": "medi_class_name", "disp_format": "", "filter_type": "Medicine", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "1", "can_calc": "0", "data_code": "amount", "data_name": "数量", "data_type": "decimal", "conv_table": [], "data_class": "実施薬剤(分解)", "field_name": "amount", "disp_format": "0", "filter_type": "Medicine", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "錠", "can_calc": "0", "data_code": "unit", "data_name": "単位", "data_type": "string", "conv_table": [], "data_class": "実施薬剤(分解)", "field_name": "unit", "disp_format": "", "filter_type": "Medicine", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "1", "can_calc": "0", "data_code": "receipt_value", "data_name": "数量(レセ)", "data_type": "decimal", "conv_table": [], "data_class": "実施薬剤(分解)", "field_name": "receipt_value", "disp_format": "0", "filter_type": "Medicine", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "本", "can_calc": "0", "data_code": "unit_second", "data_name": "単位(レセ)", "data_type": "string", "conv_table": [], "data_class": "実施薬剤(分解)", "field_name": "unit_second", "disp_format": "", "filter_type": "Medicine", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "", "can_calc": "0", "data_code": "med_in_hospital_cd_1", "data_name": "実施薬剤連携コード１", "data_type": "string", "conv_table": [], "data_class": "実施薬剤(分解)", "field_name": "med_in_hospital_cd_1", "disp_format": "", "filter_type": "Medicine", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "", "can_calc": "0", "data_code": "med_in_hospital_cd_2", "data_name": "実施薬剤連携コード２", "data_type": "string", "conv_table": [], "data_class": "実施薬剤(分解)", "field_name": "med_in_hospital_cd_2", "disp_format": "", "filter_type": "Medicine", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "", "can_calc": "0", "data_code": "med_in_hospital_cd_3", "data_name": "実施薬剤連携コード３", "data_type": "string", "conv_table": [], "data_class": "実施薬剤(分解)", "field_name": "med_in_hospital_cd_3", "disp_format": "", "filter_type": "Medicine", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}, {"preview": "", "can_calc": "0", "data_code": "med_in_hospital_cd_4", "data_name": "実施薬剤連携コード４", "data_type": "string", "conv_table": [], "data_class": "実施薬剤(分解)", "field_name": "med_in_hospital_cd_4", "disp_format": "", "filter_type": "Medicine", "data_category": "実績", "facility_table": "", "facility_filter_type": "0"}]'::jsonb, '1', '{"applications": [1]}'::jsonb, '{"classes": [1, 2, 3]}'::jsonb, '実績：実施薬剤（分解） @ordNo 使用', '2021-11-05 11:30:03.000', CURRENT_TIMESTAMP, NULL);
INSERT INTO ntss.sys_data_set
(sql_cd, "sql", db_class, detail, can_repeat, use_application, report_class, memo, reg_date, up_date, pre_sql_info)
VALUES(201, 'with prescription_tbl as ( 
	SELECT a.* FROM ( 
		SELECT
			(o ->> ''Rp'') AS rp
			,(o ->> ''sub_no'') as sub_no
			, (o ->> ''F1'') AS issue_name--調剤指示名
			, CASE WHEN (o ->> ''type'') IN (''3'', ''5'') THEN (o ->> ''F2'') || '' '' || (o ->> ''F3'') || '' '' || (o ->> ''F4'')
				ELSE (o ->> ''F2'') END AS usage_detail--用法詳細
			, op.ord_prescription_no AS ord_prescription_no 
			, CASE WHEN (o ->> ''F5'') = ''0'' or (o ->> ''F5'') = '''' then '' '' ELSE (o ->> ''F5'') END AS day_count
			, CASE WHEN (o ->> ''F5'') = ''0'' or (o ->> ''F5'') = '''' then '' '' ELSE (o ->> ''F6'') END AS day_count_unit
			, ROW_NUMBER() OVER (PARTITION BY  (o ->> ''Rp''),(o ->> ''sub_no'')   ORDER BY (o ->> ''Rp''),(o ->> ''sub_no'')  ASC) AS rn 
		FROM
			ord_prescription AS op
			, jsonb_array_elements(prescription_detail) AS o 
		WHERE
			op.is_disp = ''1'' 
			AND op.is_del = ''0''
			AND o ->> ''type'' <> ''1'' 
			AND o ->> ''type'' <> ''6'' 
			AND o ->> ''type'' <> ''E'' 
			AND o ->> ''type'' <> ''0'' 
			AND op.facility_cd = @facilityCd
			AND op.ord_prescription_no = @ordPrescriptionNo 
	) a 
	WHERE 
		a.rn = 1
), comont_info as (
	select 
	COALESCE(pt.rp, com1.rp) as rp,
	COALESCE(pt.sub_no, com1.sub_no) as sub_no,
	pt.issue_name,
	pt.usage_detail,
	pt.ord_prescription_no,
	pt.day_count,
	pt.day_count_unit,
	com1.issue_name as comment_info
	 from (select com.* from (SELECT
			(o ->> ''Rp'') AS rp
			,(o ->> ''sub_no'') as sub_no
			, (o ->> ''F1'') AS issue_name--調剤指示名
			, CASE WHEN (o ->> ''type'') IN (''3'', ''5'') THEN (o ->> ''F2'') || '' '' || (o ->> ''F3'') || '' '' || (o ->> ''F4'')
				ELSE (o ->> ''F2'') END AS usage_detail--用法詳細
			, op.ord_prescription_no AS ord_prescription_no 
			, CASE WHEN (o ->> ''F5'') = ''0'' or (o ->> ''F5'') = '''' then '' '' ELSE (o ->> ''F5'') END AS day_count
			, CASE WHEN (o ->> ''F5'') = ''0'' or (o ->> ''F5'') = '''' then '' '' ELSE (o ->> ''F6'') END AS day_count_unit
			, ROW_NUMBER() OVER (PARTITION BY  (o ->> ''Rp''),(o ->> ''sub_no'')   ORDER BY (o ->> ''Rp''),(o ->> ''sub_no'') ASC) AS rn 
		FROM
			ord_prescription AS op
			, jsonb_array_elements(prescription_detail) AS o 
		WHERE
			op.is_disp = ''1'' 
			AND op.is_del = ''0''
			AND o ->> ''type'' = ''6'' 
			AND op.facility_cd = @facilityCd
			AND op.ord_prescription_no = @ordPrescriptionNo  )  com where com.rn = 1 	AND com.issue_name <>'''' ) com1  
			FULL OUTER JOIN prescription_tbl pt 
		on pt.rp = com1.rp and pt.sub_no = com1.sub_no
) 
SELECT
	ord_pt.rp
	, ord_pt.unchg
	, ord_pt.pat_req
	, ord_pt.medicine_name
	, ord_pt.mix_name
	, coin.issue_name
	, coin.usage_detail 
	, ord_pt.rst_value
	, ord_pt.unit
	, ord_pt.r
	, coin.day_count
	, coin.day_count_unit
	, ord_pt.ord_prescription_no
	, coin.comment_info
FROM ( 
	SELECT
		json_idx
		,	(o ->> ''Rp'') AS rp
		,(o ->> ''sub_no'') AS sub_no
		, CASE WHEN ( o ->> ''unchg'' ) = ''x'' THEN ''2'' ELSE ''1'' END AS unchg--後発不可
		, CASE WHEN ( o ->> ''pat_req'' ) = ''x'' THEN ''2'' ELSE ''1'' END AS pat_req--患者希望
		, (o ->> ''F1'') AS medicine_name--薬剤名
		, (o ->> ''F2'') AS mix_name--用法
		, ( o ->> ''F5'' ) AS rst_value--量
		, ( o ->> ''F6'' ) AS unit--単位
		, ( o ->> ''R'' ) AS r --薬剤処方箋用表示
		, op.ord_prescription_no AS ord_prescription_no 
	FROM
		ord_prescription AS op
		cross join lateral jsonb_array_elements(prescription_detail) with ordinality as tmp(o, json_idx)
	WHERE
		op.is_disp = ''1'' 
		AND op.is_del = ''0'' 
		AND o ->> ''type'' = ''1''
		AND op.facility_cd = @facilityCd
		AND op.ord_prescription_no = @ordPrescriptionNo 
) ord_pt
left join comont_info coin 
		on coin.rp = ord_pt.rp and coin.sub_no = ord_pt.sub_no
ORDER BY ord_pt.json_idx ASC
', 2, '[{"preview": "✓", "can_calc": "0", "data_code": "unchg", "data_name": "後発不可", "data_type": "string", "conv_table": [{"code": "1", "disp": "", "item": "可"}, {"code": "2", "disp": "✓", "item": "不可"}], "data_class": "薬剤情報", "field_name": "unchg", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "✓", "can_calc": "0", "data_code": "pat_req", "data_name": "患者希望", "data_type": "string", "conv_table": [{"code": "1", "disp": "", "item": "希望しない"}, {"code": "2", "disp": "✓", "item": "希望する"}], "data_class": "薬剤情報", "field_name": "pat_req", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "123456", "can_calc": "0", "data_code": "Rp", "data_name": "RP番号", "data_type": "string", "conv_table": [], "data_class": "処方(詳細)", "field_name": "rp", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "調剤指示名", "can_calc": "0", "data_code": "issue_name", "data_name": "調剤指示名", "data_type": "string", "conv_table": [], "data_class": "処方(詳細)", "field_name": "issue_name", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "舌下", "can_calc": "0", "data_code": "mix_name", "data_name": "用法", "data_type": "string", "conv_table": [], "data_class": "処方(詳細)", "field_name": "mix_name", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "用法詳細", "can_calc": "0", "data_code": "usage_detail", "data_name": "用法詳細", "data_type": "string", "conv_table": [], "data_class": "処方(詳細)", "field_name": "usage_detail", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "薬剤１", "can_calc": "0", "data_code": "R", "data_name": "薬剤名称", "data_type": "string", "conv_table": [], "data_class": "処方(詳細)", "field_name": "r", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "薬剤名", "can_calc": "0", "data_code": "medicine_name", "data_name": "薬剤名", "data_type": "string", "conv_table": [], "data_class": "薬剤情報", "field_name": "medicine_name", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "1", "can_calc": "0", "data_code": "F5", "data_name": "用量", "data_type": "string", "conv_table": [], "data_class": "薬剤情報", "field_name": "rst_value", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "日分", "can_calc": "0", "data_code": "F6", "data_name": "単位", "data_type": "string", "conv_table": [], "data_class": "薬剤情報", "field_name": "unit", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "舌下", "can_calc": "0", "data_code": "mix_name", "data_name": "用法", "data_type": "string", "conv_table": [], "data_class": "薬剤情報", "field_name": "mix_name", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "7", "can_calc": "1", "data_code": "day_count", "data_name": "日数・回数", "data_type": "decimal", "conv_table": [], "data_class": "処方(詳細)", "field_name": "day_count", "disp_format": "0", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "日分", "can_calc": "1", "data_code": "day_count_unit", "data_name": "調剤単位", "data_type": "string", "conv_table": [], "data_class": "処方(詳細)", "field_name": "day_count_unit", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "日分", "can_calc": "1", "data_code": "comment_info", "data_name": "コメント", "data_type": "string", "conv_table": [], "data_class": "処方(詳細)", "field_name": "comment_info", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}]'::jsonb, '1', '{"applications": [1]}'::jsonb, '{"classes": [1, 2, 9]}'::jsonb, '処方：@facilityCd @ordPrescriptionNo  使用', '2021-11-09 13:42:00.000', CURRENT_TIMESTAMP, NULL);
INSERT INTO ntss.sys_data_set
(sql_cd, "sql", db_class, detail, can_repeat, use_application, report_class, memo, reg_date, up_date, pre_sql_info)
VALUES(206, 'WITH 
save AS (
	SELECT
		om.*,
		save.supplies_base_date,
		save.supplies_source_class,
		save.supplies_class,
		save.ind_rst_class,
		save.supplies_cd,
		save.receipt_value,
		save.ind_rst_value,
		save.medicine_mix_cd,
		save.receipt_unit,
		save.ind_unit,
		TO_NUMBER( save.supplies_cd, ''9999999999'' ) supplies_cd_n,
		kr.kur_cd,
		kr.kur_name,
		bd.bed_cd,
		bd.bed_name
	FROM
		ord_main AS om
		INNER JOIN ord_material_save AS save ON ( om.ord_no = save.supplies_base_no AND om.facility_cd = save.facility_cd AND save.ind_rst_class = ''1'' )
		LEFT OUTER JOIN mst_kur AS kr ON ( om.ind_kur_cd = kr.kur_cd AND kr.is_del = ''0'' )
		LEFT OUTER JOIN mst_bed AS bd ON ( om.ind_bed_cd = bd.bed_cd AND bd.is_del = ''0'' AND bd.is_disp = ''1'' )
	WHERE
		om.ord_no IN ( @ordNos )
		AND om.is_del = ''0''
	),
dz AS ( SELECT * FROM mst_dialyzer mst WHERE facility_cd = @facilityCd AND is_del = ''0'' AND is_disp = ''1'' ),
kr AS ( SELECT * FROM mst_kur mst WHERE facility_cd = @facilityCd AND is_del = ''0'' ),
bd AS ( SELECT * FROM mst_bed mst WHERE facility_cd = @facilityCd AND is_del = ''0'' AND is_disp = ''1'' ),
eq AS ( SELECT * FROM mst_equipment mst WHERE facility_cd = @facilityCd AND is_del = ''0'' AND is_disp = ''1'' ),
eqc AS ( SELECT * FROM mst_equipment_class mst WHERE facility_cd = @facilityCd AND is_del = ''0'' AND is_disp = ''1'' ),
md AS ( SELECT * FROM mst_medicine mst WHERE facility_cd = @facilityCd AND is_del = ''0'' AND is_disp = ''1'' ),
mdx AS ( SELECT * FROM mst_medicine_mix mst WHERE facility_cd = @facilityCd AND is_del = ''0'' AND is_disp = ''1'' ),
mdc AS ( SELECT * FROM mst_medicine_class mst WHERE facility_cd = @facilityCd AND is_del = ''0'' AND is_disp = ''1'' ) ,
		medic AS (
	SELECT
		index_no AS medic_order,
		TO_NUMBER( order_cd ->> ''code'', ''999999999999'' ) AS medic_code,
		order_cd ->> ''name'' AS medi_name
	FROM
		mst_selector
		CROSS JOIN LATERAL jsonb_array_elements ( order_settings -> ''items'' ) WITH ORDINALITY AS tmp ( order_cd, index_no )
	WHERE
		facility_cd = @facilityCd
		AND master_physical_name = ''mst_medicine_class''
	),equic AS (
	SELECT
		index_no AS equic_order,
		TO_NUMBER( order_cd ->> ''code'', ''999999999999'' ) AS equic_code,
		order_cd ->> ''name'' AS equic_name
	FROM
		mst_selector
		CROSS JOIN LATERAL jsonb_array_elements ( order_settings -> ''items'' ) WITH ORDINALITY AS tmp ( order_cd, index_no )
	WHERE
		facility_cd = @facilityCd
		AND master_physical_name = ''mst_equipment_class''
	),medi_mix AS (
	SELECT
		index_no AS medi_mix_order,
		TO_NUMBER( order_cd ->> ''code'', ''999999999999'' ) AS medi_mix_code,
		order_cd ->> ''name'' AS medi_mix_name
	FROM
		mst_selector
		CROSS JOIN LATERAL jsonb_array_elements ( order_settings -> ''items'' ) WITH ORDINALITY AS tmp ( order_cd, index_no )
	WHERE
		facility_cd = @facilityCd
		AND master_physical_name = ''mst_medicine_class''
	),dia AS (
	SELECT
		index_no AS dia_order,
		TO_NUMBER( order_cd ->> ''code'', ''999999999999'' ) AS dia_code,
		order_cd ->> ''name'' AS equi_name
	FROM
		mst_selector
		CROSS JOIN LATERAL jsonb_array_elements ( order_settings -> ''items'' ) WITH ORDINALITY AS tmp ( order_cd, index_no )
	WHERE
		facility_cd = @facilityCd
		AND master_physical_name = ''mst_dialyzer''
	)
, bed_sort AS (
	SELECT
		index_no AS bed_order,
		TO_NUMBER( order_cd ->> ''code'', ''999999999999'' ) AS bed_code,
		order_cd ->> ''name'' AS bed_sort_name
	FROM
		mst_selector
		CROSS JOIN LATERAL jsonb_array_elements ( order_settings -> ''items'' ) WITH ORDINALITY AS tmp ( order_cd, index_no )
	WHERE
		facility_cd = @facilityCd
		AND master_physical_name = ''mst_bed''
),
	result_all as (
	SELECT
	disp_order,
to_timestamp( treat_date, ''YYYYMMDD'' ) AS treat_date,
kind,
class,
class_data_order,
class_cd,
do_action,
NAME,
code,
kur_cd,
kur_name,
Amount AS amount,
unit,
bed_cd,
bed_name,
pat_id,
pat_id AS pat_id1,
in_hospital_cd_1,
in_hospital_cd_2,
in_hospital_cd_3,
in_hospital_cd_4,
data_type_order,
kind_order,
dia.dia_order,
medic.medic_order,
equic.equic_order,
medi_mix.medi_mix_order,
bed.bed_order
FROM
	(
	SELECT
		@equsort AS disp_order,
		save.supplies_base_date as treat_date,
		save.kur_cd,
		COALESCE ( save.kur_name, ''未登録'' ) AS kur_name,
		save.bed_cd,
		COALESCE ( save.bed_name, ''未登録'' ) AS bed_name,
		save.pat_id,
    ''ダイアライザ'' AS class,
		1 as class_data_order,
	CASE

			WHEN dz.model_number IS NOT NULL THEN
			''ダイアライザ'' ELSE NULL
		END AS kind,
		''0'' AS class_cd,
		''ダイアライザ'' AS do_action, 
		dz.model_number AS NAME,
		TO_NUMBER(save.supplies_cd, ''99999999'' ) AS code,
    CAST(NULLIF(save.ind_rst_value, '''') AS DECIMAL) AS Amount,
		COALESCE ( save.ind_unit, '''' ) AS Unit,
		dz.in_hospital_cd_1,
		dz.in_hospital_cd_2,
		dz.in_hospital_cd_3,
		dz.in_hospital_cd_4,
		''医療材料'' AS data_type_order,
		2 AS kind_order,
		NULL AS equipment_cd,
		NULL AS equipment_class_cd,
		NULL AS medicine_cd,
		NULL AS medicine_class_cd,
		dz.dialyzer_cd
	FROM
		save
		INNER JOIN dz ON TO_NUMBER(save.supplies_cd, ''99999999'' ) = dz.dialyzer_cd
		AND dz.dialyzer_cd IN ( @diaIds )
	WHERE
		save.supplies_source_class = ''0''
		and save.supplies_class = ''01''
	UNION ALL--吸着カラム
	SELECT
		@equsort AS disp_order,
		save.supplies_base_date as treat_date,
		save.kur_cd,
		COALESCE ( save.kur_name, ''未登録'' ) AS kur_name,
		save.bed_cd,
		COALESCE ( save.bed_name, ''未登録'' ) AS bed_name,
		save.pat_id,
    ''吸着カラム'' AS class,
		3 as class_data_order,
	CASE

			WHEN eqc.class_name IS NULL THEN
			''未分類'' ELSE COALESCE ( eqc.class_name, '''' )
		END AS kind,
	CASE
			WHEN eqc.class_name IS NULL THEN
			''-1'' ELSE eqc.class_cd
		END AS class_cd,
		''医材'' AS do_action, 
		eq.equipment_name AS NAME,
		TO_NUMBER(save.supplies_cd, ''99999999'' ) AS code,
		CAST(NULLIF(save.ind_rst_value, '''') AS DECIMAL) AS Amount,
		COALESCE ( save.ind_unit, '''' ) AS Unit,
		eq.in_hospital_cd_1,
		eq.in_hospital_cd_2,
		eq.in_hospital_cd_3,
		eq.in_hospital_cd_4,
		''医療材料'' AS data_type_order,
		1 AS kind_order,
		eq.equipment_cd AS equipment_cd,
		eqc.class_cd AS equipment_class_cd,
		NULL AS medicine_cd,
		NULL AS medicine_class_cd,
		NULL AS dialyzer_cd
	FROM
		save
		INNER JOIN eq ON TO_NUMBER(save.supplies_cd, ''99999999'' ) = eq.equipment_cd
		AND eq.class_cd IN ( @eqIds )
		LEFT OUTER JOIN eqc ON eq.class_cd = eqc.class_cd
	WHERE
		save.supplies_source_class = ''0''
		and save.supplies_class = ''02''
	UNION ALL--1次膜
	SELECT
		@equsort AS disp_order,
		save.supplies_base_date as treat_date,
		save.kur_cd,
		COALESCE ( save.kur_name, ''未登録'' ) AS kur_name,
		save.bed_cd,
		COALESCE ( save.bed_name, ''未登録'' ) AS bed_name,
		save.pat_id,
    ''1次膜'' AS class,
		4 as class_data_order,
	CASE

			WHEN eqc.class_name IS NULL THEN
			''未分類'' ELSE COALESCE ( eqc.class_name, '''' )
