		, NAME
		, code
		, SUM(medInfo.ind_rst_value) AS Amount
		, Unit
		, in_hospital_cd_1
		, in_hospital_cd_2
		, in_hospital_cd_3
		, in_hospital_cd_4
		, ''薬剤'' AS data_type_order
		,	1 AS kind_order
		, NULL AS equipment_cd
		, NULL AS equipment_class_cd
		, code::TEXT AS medicine_cd
		, class_cd::TEXT AS medicine_class_cd
		, NULL AS dialyzer_cd
	FROM (
		SELECT
			save.supplies_base_date as treat_date,
			save.kur_cd,
			COALESCE ( save.kur_name, ''未登録'' ) AS kur_name,
			save.bed_cd,
			COALESCE ( save.bed_name, ''未登録'' ) AS bed_name,
			save.pat_id,
			CASE
				WHEN mdc.class_name IS NULL THEN
				''未分類'' ELSE COALESCE ( mdc.class_name, '''' )
				END AS class,
				13 as class_data_order,
			CASE
				WHEN mdc.class_name IS NULL THEN
				''未分類'' ELSE COALESCE ( mdc.class_name, '''' )
				END AS kind,
			CASE
				WHEN mdc.class_name IS NULL THEN
				''-1'' ELSE mdc.class_cd
				END AS class_cd,
			md.medicine_name AS NAME,
			TO_NUMBER(save.supplies_cd, ''99999999'' ) AS code,
			CAST(NULLIF(save.ind_rst_value, '''') AS DECIMAL) AS ind_rst_value ,
			COALESCE ( save.ind_unit, '''' ) AS Unit,
			md.in_hospital_cd_1,
			md.in_hospital_cd_2,
			md.in_hospital_cd_3,
			md.in_hospital_cd_4
		FROM
			save
			INNER JOIN md ON TO_NUMBER( save.supplies_cd, ''99999999'' ) = md.medicine_cd
			AND md.class_cd IN ( @medIds )
			LEFT OUTER JOIN mdc ON md.class_cd = mdc.class_cd
		WHERE
			save.supplies_source_class = ''1''
		and save.supplies_class = ''12''
	) medInfo
	GROUP BY
		treat_date,
		kind,
		class_cd,
		class,
		class_data_order,
		do_action,
		NAME,
		code,
		kur_cd,
		kur_name,
		bed_cd,
		bed_name,
		Unit,
		pat_id,
		disp_order,
		in_hospital_cd_1,
		in_hospital_cd_2,
		in_hospital_cd_3,
		in_hospital_cd_4,
		data_type_order,
		kind_order
	ORDER BY
		disp_order,
		kind,
		class_cd,
		do_action,
		data_type_order,
		kind_order,
		code,
		NAME,
		kur_cd,
		kur_name,
		bed_cd,
		bed_name,
		pat_id
	)
	UNION ALL--投薬調製薬剤
	(SELECT
		@medsort AS disp_order
		, treat_date
		, kur_cd
		, kur_name
		, bed_cd
		, bed_name
		, pat_id
		, class
		, class_data_order
		, kind
		, class_cd
		, ''通常薬剤'' AS do_action
		, NAME
		, code
		, SUM(medInfo.ind_rst_value) AS Amount
		, Unit
		, in_hospital_cd_1
		, in_hospital_cd_2
		, in_hospital_cd_3
		, in_hospital_cd_4
		, ''薬剤'' AS data_type_order
		,	1 AS kind_order
		, NULL AS equipment_cd
		, NULL AS equipment_class_cd
		, code::TEXT AS medicine_cd
		, class_cd::TEXT AS medicine_class_cd
		, NULL AS dialyzer_cd
	FROM (
		SELECT
			save.supplies_base_date as treat_date,
			save.kur_cd,
			COALESCE ( save.kur_name, ''未登録'' ) AS kur_name,
			save.bed_cd,
			COALESCE ( save.bed_name, ''未登録'' ) AS bed_name,
			save.pat_id,
			CASE
				WHEN mdc.class_name IS NULL THEN
				''未分類'' ELSE COALESCE ( mdc.class_name, '''' )
				END AS class,
				13 as class_data_order,
			CASE
				WHEN mdc.class_name IS NULL THEN
				''未分類'' ELSE COALESCE ( mdc.class_name, '''' )
				END AS kind,
			CASE
				WHEN mdc.class_name IS NULL THEN
				''-1'' ELSE mdc.class_cd
				END AS class_cd,
			md.medicine_name AS NAME,
			TO_NUMBER(save.supplies_cd, ''99999999'' ) AS code,
			CAST(NULLIF(save.ind_rst_value, '''') AS DECIMAL) AS ind_rst_value ,
			COALESCE ( save.ind_unit, '''' ) AS Unit,
			md.in_hospital_cd_1,
			md.in_hospital_cd_2,
			md.in_hospital_cd_3,
			md.in_hospital_cd_4
		FROM
			save
			INNER JOIN md ON TO_NUMBER( save.supplies_cd, ''99999999'' )  = md.medicine_cd
			AND md.class_cd IN ( @medIds )
			LEFT OUTER JOIN mdc ON md.class_cd = mdc.class_cd
		WHERE
			save.supplies_source_class = ''1''
		and save.supplies_class = ''20''
	) medInfo
	GROUP BY
		treat_date,
		kind,
		class_cd,
		class,
		class_data_order,
		do_action,
		NAME,
		code,
		kur_cd,
		kur_name,
		bed_cd,
		bed_name,
		Unit,
		pat_id,
		disp_order,
		in_hospital_cd_1,
		in_hospital_cd_2,
		in_hospital_cd_3,
		in_hospital_cd_4,
		data_type_order,
		kind_order
	ORDER BY
		disp_order,
		kind,
		class_cd,
		do_action,
		data_type_order,
		kind_order,
		code,
		NAME,
		kur_cd,
		kur_name,
		bed_cd,
		bed_name,
		pat_id
	)
	) AS EquipmentList
	LEFT OUTER JOIN medic ON medic.medic_code :: TEXT = EquipmentList.medicine_class_cd
	LEFT OUTER JOIN equic ON equic.equic_code = EquipmentList.equipment_class_cd
	LEFT OUTER JOIN dia ON dia.dia_code = EquipmentList.dialyzer_cd
	LEFT OUTER JOIN medi_mix ON medi_mix.medi_mix_code :: TEXT = EquipmentList.medicine_class_cd
	LEFT OUTER JOIN bed_sort AS bed ON bed.bed_code = EquipmentList.bed_cd
) 
